mapper.select:
select l.id, l.operate_emp_id, l.`module`, l.operate_type, l.operate_time,
       l.class_name, l.method_name, l.method_params, l.return_value,
       l.cost_time, l.`status`, l.error_msg,
       e.name as operateEmpName
from operate_log l
         left join emp e on l.operate_emp_id = e.id


        l.`module` like concat('%',#{module},'%')


        and l.operate_type = #{operateType}


        and l.operate_emp_id = #{operateEmpId}


        and l.`status` = #{status}


        and l.operate_time  >= #{begin}


        and l.operate_time < date_add(#{end}, interval 1 day)


order by l.operate_time desc, l.id desc
